  const runSearch = () => {
    const query = document.querySelector('#searchInput').value.trim();
    const normalized = query.toLowerCase();
    const tokenize = value => {
      const found = [];
      const matcher = /"([^"]*)"|#[\w-]+|\(|\)|\b(?:and|or|not)\b|[^\s()]+/gi;
      let match;
      while ((match = matcher.exec(value)) !== null) {
        const raw = match[0], lower = raw.toLowerCase();
        if (raw.startsWith('"')) found.push({type:'term', value:match[1].toLowerCase()});
        else if (raw === '(') found.push({type:'open'});
        else if (raw === ')') found.push({type:'close'});
        else if (['and','or','not'].includes(lower)) found.push({type:lower});
        else if (raw.startsWith('#')) found.push({type:'label', value:raw.slice(1).toLowerCase()});
        else found.push({type:'term', value:lower});
      }
      const tokens = [];
      found.forEach(current => {
        const previous = tokens[tokens.length - 1];
        const previousEnds = previous && ['term','label','close'].includes(previous.type);
        const currentStarts = ['term','label','open','not'].includes(current.type);
        if (previousEnds && currentStarts) tokens.push({type:'and'});
        tokens.push(current);
      });
      return tokens;
    };
    const compile = value => {
      const tokens = tokenize(value); let position = 0;
      const primary = () => {
        const token = tokens[position++];
